const segmentColSel = document.getElementById('segment-col');
const binCountSel = document.getElementById('bin-count');
const analyzeBtn = document.getElementById('analyze-btn');
const errorMsg = document.getElementById('error-msg');
const results = document.getElementById('results');

fileInput.addEventListener('change', (e) => {
  const file = e.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = (ev) => loadCsv(ev.target.result, file.name);
  reader.readAsText(file);
});

demoBtn.addEventListener('click', () => loadCsv(DEMO_CSV, 'football_calibration_demo.csv (built-in)'));
analyzeBtn.addEventListener('click', runAnalysis);
downloadSampleBtn.addEventListener('click', downloadSample);

/* ---- sample CSV download ------------------------------------------------*/
function downloadSample() {
  const blob = new Blob([SAMPLE_CSV], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'calibration_checker_sample.csv';
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

/* ---- CSV loading -------------------------------------------------------*/
function loadCsv(csvText, label) {
  clearError();
  const parsed = Papa.parse(csvText, { header: true, dynamicTyping: true, skipEmptyLines: true });
  if (parsed.errors && parsed.errors.length) {
    showError(`Could not parse CSV: ${parsed.errors[0].message}`);
    return;
  }
  parsedRows = parsed.data;
  headers = parsed.meta.fields || [];
  if (!parsedRows.length || !headers.length) {
    showError('CSV looks empty, or has no header row.');
    return;
  }

  fileStatus.textContent = `${label}, ${parsedRows.length.toLocaleString()} rows, ${headers.length} columns`;
  populateColumnSelectors();
  mappingRow.classList.remove('hidden');
  results.classList.add('hidden');
}

function populateColumnSelectors() {
  const guessPred = headers.find((h) => /^(predicted_?prob|prob(ability)?|p_?hat|score)$/i.test(h)) || headers[0];
  const guessOutcome = headers.find((h) => /^(outcome|actual|label|target|y|win)$/i.test(h)) || headers[1] || headers[0];
  const guessSegment = headers.find((h) => /^(segment|group|tier|category|bucket)$/i.test(h));

  for (const sel of [predColSel, outcomeColSel]) sel.innerHTML = '';
  segmentColSel.innerHTML = '<option value="">— none —</option>';

  headers.forEach((h) => {
    predColSel.appendChild(new Option(h, h));
    outcomeColSel.appendChild(new Option(h, h));
    segmentColSel.appendChild(new Option(h, h));
  });

  predColSel.value = guessPred;
  outcomeColSel.value = guessOutcome;
  segmentColSel.value = guessSegment || '';
}

/* ---- analysis ------------------------------------------------------------*/
function runAnalysis() {
  clearError();
  const predCol = predColSel.value;
  const outcomeCol = outcomeColSel.value;
  const segCol = segmentColSel.value || null;
  const nBins = parseInt(binCountSel.value, 10);

  if (predCol === outcomeCol) {
    showError('Predicted-probability column and outcome column must be different.');
    return;
  }

  const rows = parsedRows
    .map((r) => ({
      p: Number(r[predCol]),
      y: Number(r[outcomeCol]),
      seg: segCol ? r[segCol] : null,
    }))
    .filter((r) => Number.isFinite(r.p) && Number.isFinite(r.y) && r.p >= 0 && r.p <= 1 && (r.y === 0 || r.y === 1));

  if (rows.length < 10) {
    showError(`Only ${rows.length} usable rows after cleaning. Need probabilities in [0,1] and outcomes coded 0/1.`);
    return;
  }

  const overallBrier = brierScore(rows);
  const baseRate = rows.reduce((s, r) => s + r.y, 0) / rows.length;
  const climBrier = baseRate * (1 - baseRate);
  const overallRel = reliabilityBins(rows, nBins);

  renderStats(overallBrier, climBrier, rows, baseRate);
  renderReliabilityChart('reliability-chart-overall', [
    buildDataset(`All observations (n=${rows.length})`, overallRel, resolveColor(SERIES_COLORS[0])),
  ]);

  const distinctSegments = segCol
    ? [...new Set(rows.map((r) => r.seg).filter(isValidSegment))].sort()
    : [];
  let segStats = null;

  if (distinctSegments.length > 1 && distinctSegments.length <= 6) {
    segStats = distinctSegments.map((seg, i) => {
      const segRows = rows.filter((r) => r.seg === seg);
      return {
        seg,
        brier: brierScore(segRows),
        n: segRows.length,
        share: segRows.length / rows.length,
        color: resolveColor(SERIES_COLORS[i % SERIES_COLORS.length]),
        rel: reliabilityBins(segRows, Math.min(nBins, 5)),
      };
    });

    renderReliabilityChart(
      'reliability-chart-segment',
      segStats.map((s) => buildDataset(`${s.seg} (n=${s.n})`, s.rel, s.color))
    );
    renderSegmentTable(segStats);
    document.getElementById('segment-chart-wrap').classList.remove('hidden');
    document.getElementById('segment-table-wrap').classList.remove('hidden');
  } else {
    document.getElementById('segment-chart-wrap').classList.add('hidden');
    document.getElementById('segment-table-wrap').classList.add('hidden');
  }

  renderInsights(overallBrier, climBrier, overallRel, segStats);
  results.classList.remove('hidden');
}

function isValidSegment(seg) {
  if (seg === null || seg === undefined) return false;
  if (typeof seg === 'number' && Number.isNaN(seg)) return false;
  if (typeof seg === 'string' && seg.trim() === '') return false;
  return true;
}

function brierScore(rows) {
  return rows.reduce((sum, r) => sum + (r.p - r.y) ** 2, 0) / rows.length;
}

function reliabilityBins(rows, nBins) {
  const buckets = Array.from({ length: nBins }, () => ({ sumP: 0, sumY: 0, n: 0 }));
  rows.forEach((r) => {
    const idx = Math.min(nBins - 1, Math.floor(r.p * nBins));
    buckets[idx].sumP += r.p;
    buckets[idx].sumY += r.y;
    buckets[idx].n += 1;
  });
  return buckets
    .filter((b) => b.n > 0)
    .map((b) => ({ meanPred: b.sumP / b.n, empFreq: b.sumY / b.n, n: b.n }));
}

function buildDataset(label, rel, color) {
  return {
    label,
    data: rel.map((b) => ({ x: b.meanPred, y: b.empFreq, n: b.n })),
    borderColor: color,
    backgroundColor: color,
    pointRadius: 5,
    pointHoverRadius: 7,
    borderWidth: 2,
    showLine: true,
    tension: 0,
  };
}

/* ---- insights ------------------------------------------------------------
 * A small rule-based commentary generator. It only looks at the numbers
 * that were just computed, so it applies equally to the football demo or
 * to whatever CSV someone drops in.
 * ----------------------------------------------------------------------- */
function renderInsights(overallBrier, climBrier, overallRel, segStats) {
  const notes = [];

  // 1. overall calibration quality, relative to a naive "always predict the
  //    base rate" forecaster.
  const skill = climBrier > 0 ? 1 - overallBrier / climBrier : null;
  let qualityLabel = 'not very informative here';
  if (skill !== null) {
    if (skill > 0.3) qualityLabel = 'a solid improvement over guessing the base rate, and the shape of the curve below is generally close to the diagonal';
    else if (skill > 0.1) qualityLabel = 'somewhat better than guessing the base rate, but there is visible room to tighten it up';
    else if (skill > 0) qualityLabel = 'only marginally better than a model that ignores the inputs entirely and always predicts the base rate';
    else qualityLabel = 'no better than guessing the base rate, the predictions are not adding much signal';
  }
  notes.push(
    `Overall Brier score is <strong>${overallBrier.toFixed(4)}</strong>, versus <strong>${climBrier.toFixed(4)}</strong> for a naive forecaster that always predicts the base rate. That is ${qualityLabel}.`
  );

  // 2. directional bias: compare the calibration gap (observed minus
  //    predicted) below and above the 50% mark.
  const weightedGap = (bins) => {
    const totalN = bins.reduce((s, b) => s + b.n, 0);
    if (totalN < 20) return null;
    return bins.reduce((s, b) => s + b.n * (b.empFreq - b.meanPred), 0) / totalN;
  };
  const lowGap = weightedGap(overallRel.filter((b) => b.meanPred < 0.5));
  const highGap = weightedGap(overallRel.filter((b) => b.meanPred >= 0.5));
  const THRESH = 0.03;

  if (highGap !== null && highGap > THRESH) {
    notes.push(
      `Above the 50% mark, observed frequency runs about <strong>${(highGap * 100).toFixed(1)} points higher</strong> than predicted. The model is a bit underconfident about the outcomes it already favors, sometimes called a favorite-longshot pattern in betting markets.`
    );
  } else if (highGap !== null && highGap < -THRESH) {
    notes.push(
      `Above the 50% mark, observed frequency runs about <strong>${Math.abs(highGap * 100).toFixed(1)} points lower</strong> than predicted. The model is overconfident about its most likely outcomes.`
    );
  }
  if (lowGap !== null && lowGap < -THRESH) {
    notes.push(
      `Below the 50% mark, the outcome happens <strong>less often</strong> than predicted (gap of ${(lowGap * 100).toFixed(1)} points). Low-probability predictions are being overpriced.`
    );
  } else if (lowGap !== null && lowGap > THRESH) {
    notes.push(
      `Below the 50% mark, the outcome happens <strong>more often</strong> than predicted (gap of ${(lowGap * 100).toFixed(1)} points). Low-probability predictions are being underpriced.`
    );
  }
  if ((highGap === null || Math.abs(highGap) <= THRESH) && (lowGap === null || Math.abs(lowGap) <= THRESH)) {
    notes.push('No strong directional bias shows up: the curve tracks the diagonal fairly closely across the probability range.');
  }

  // 3. segment-level notes.
  if (segStats && segStats.length) {
    const worst = [...segStats].sort((a, b) => b.brier - a.brier)[0];
    const best = [...segStats].sort((a, b) => a.brier - b.brier)[0];
    let flaggedSpread = false;
    if (worst.seg !== best.seg && worst.brier - overallBrier > 0.02) {
      notes.push(
        `Segment <strong>"${worst.seg}"</strong> is the least well calibrated (Brier ${worst.brier.toFixed(4)}), noticeably worse than the overall ${overallBrier.toFixed(4)}.`
      );
      flaggedSpread = true;
    }

    const smallSegments = segStats.filter((s) => s.share < 0.10);
    smallSegments.forEach((s) => {
      notes.push(
        `Segment <strong>"${s.seg}"</strong> is only <strong>${(s.share * 100).toFixed(1)}%</strong> of the data (n=${s.n}), so its calibration numbers are noisy and should be read with caution.`
      );
    });

    if (!flaggedSpread && !smallSegments.length) {
      notes.push('Calibration looks fairly consistent across segments, no single group stands out as clearly worse or under-sampled.');
    }
  }

  const list = document.getElementById('insights-list');
  list.innerHTML = notes.map((n) => `<li>${n}</li>`).join('');
  document.getElementById('insights-panel').classList.remove('hidden');
}

/* ---- rendering ---------------------------------------------------------*/
function renderStats(brier, climBrier, rows, baseRate) {
  document.getElementById('brier-overall').textContent = brier.toFixed(4);
  document.getElementById('brier-baseline-note').textContent =
    `lower is better, 0 = perfect, ${climBrier.toFixed(4)} = naive base-rate baseline here`;
  document.getElementById('stat-n').textContent = rows.length.toLocaleString();
  document.getElementById('stat-base-rate').textContent = `base rate: ${(baseRate * 100).toFixed(1)}% positive`;
}

function renderSegmentTable(segStats) {
  const tbody = document.querySelector('#segment-table tbody');
  tbody.innerHTML = '';
  segStats.forEach((s) => {
    const tr = document.createElement('tr');
    tr.innerHTML = `<td><span class="seg-swatch" style="background:${s.color}"></span>${s.seg}</td><td>${s.brier.toFixed(4)}</td><td>${s.n.toLocaleString()}</td><td>${(s.share * 100).toFixed(1)}%</td>`;
    tbody.appendChild(tr);
  });
}

function renderReliabilityChart(canvasId, datasets) {
  const ctx = document.getElementById(canvasId);
  const diagonalColor = resolveColor('var(--diagonal-line)');
  const gridline = resolveColor('var(--gridline)');
  const textSecondary = resolveColor('var(--text-secondary)');

  const diagonal = {
    label: 'Perfect calibration',
    data: [{ x: 0, y: 0 }, { x: 1, y: 1 }],
    borderColor: diagonalColor,
    borderDash: [6, 5],
    borderWidth: 2,
    pointRadius: 0,
    showLine: true,
    order: 99,
  };

  if (chartInstances[canvasId]) chartInstances[canvasId].destroy();
  chartInstances[canvasId] = new Chart(ctx, {
    type: 'scatter',
    data: { datasets: [diagonal, ...datasets] },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      scales: {
        x: {
          min: 0, max: 1,
          title: { display: true, text: 'Predicted probability', color: textSecondary },
          ticks: { color: textSecondary, callback: (v) => `${Math.round(v * 100)}%` },
          grid: { color: gridline },
        },
        y: {
          min: 0, max: 1,
          title: { display: true, text: 'Observed frequency', color: textSecondary },
          ticks: { color: textSecondary, callback: (v) => `${Math.round(v * 100)}%` },
          grid: { color: gridline },
        },
      },
      plugins: {
        legend: { labels: { color: textSecondary, usePointStyle: true } },
        tooltip: {
          callbacks: {
            label: (item) => {
              const d = item.raw;
              if (d.n === undefined) return item.dataset.label;
              return `${item.dataset.label}: predicted ${(d.x * 100).toFixed(1)}% -> observed ${(d.y * 100).toFixed(1)}% (n=${d.n})`;
            },
          },
        },
      },
    },
  });
}

function showError(msg) {
  errorMsg.textContent = msg;
  errorMsg.classList.remove('hidden');
}
function clearError() {
  errorMsg.classList.add('hidden');
  errorMsg.textContent = '';
}
